add('a-i','Explain the term ‘intrapreneur’.',5,'business-1-5','definition-of-intrapreneur',['Explain entrepreneurial activity or new ideas within the business where the person is employed. The definition carries 3 + 2 marks.'],[response(1,'Definition',[('explain','First element of explanation',3),('develop','Second element of explanation',2)])],[14],[])
add('a-ii','Illustrate, using examples from the above text, how ‘intrapreneurship’ benefits Castlewest Hotel and Conference Centre.',15,'business-1-5','benefits-of-intrapreneurship',['Illustrate two benefits with separate relevant case links. The scheme awards 8 marks (4 + 4) and 7 marks (4 + 3).'],[response(i,f'Benefit {i} · {4+link} marks',[('explain','Benefit explained',4),('link','Separate relevant link',link)]) for i,link in enumerate([4,3],1)],[14])
